def write(rows, fn):
    with open(os.path.join(W, fn), 'w', encoding='utf-8-sig', newline='') as f:
        w = csv.writer(f)
        w.writerow(['block', 'pair', 'old_lines', 'new_lines', 'current_line(88abe4e7)', 'errata_id', 'used_version', 'verdict', 'evidence_numbers', 'evidence_path', 'note'])
        for b, e, v, j, num, p, note in rows:
            o = mp.get(b)
            if o:
                cl = ';'.join(str(r['now_line']) for r in o['now'] if r['now_line'])
                w.writerow([b, o['pair'], f"{o['old'][0]}-{o['old'][1]}", f"{o['new'][0]}-{o['new'][1]}", cl, e, v, j, num, p, note])
            else:
                w.writerow([b, 'figs', '', '', '196-197', e, v, j, num, p, note])
    print(fn, len(rows), Counter(r[3] for r in rows))


write(V89, 'audit_v8_v9.csv')
write(V47, 'audit_v4_v7.csv')
